}

// ---------- state ----------
function newState(oid, p) {
  return {
    v: 1, oid, ph: 'new', p, ed: null, pol: null, D: null, cust: null, em: null, cur: null, items: [],
    fl: [], tot: 0, cr: null, fr: null, rv: null, cl: null, ac: [], stopped: false, oend: false,
    os: {}, ek: {}, nt: {}, tk: {}, ob: {},
  };
