    return;
  }
  e.r = st === 'ok' ? 'ok' : st === 'error' ? 'err' : 'unk';
  e.p = perm;
  e.c = code;
  if (st === 'ok' && e.t === 'al') e.plan = [P.result, P.items, P].find(x => x && typeof x === 'object' && (Array.isArray(x) || Array.isArray(x.fulfilments)));
