211	function onResult(w, P) {
212	  const C = w.C;
213	  const err = P.error;
214	  const code = err && typeof err === 'object' ? String(err.code ?? '') : String(err ?? '');
215	  const retry = P.retryable ?? (err && typeof err === 'object' ? err.retryable : undefined);
216	  const perm = retry !== true;
217	  const st = P.status;
218	  const e = C.ek[P.key];
219	  if (!e) {
220	    const keys = (P.items || []).map(x => x && x.key).filter(k => k && C.ek[k] && C.ek[k].t === 'it');
