489	// ---------- phases of the order ----------
490	// ph: new -> alloc -> create -> fraud -> (review) -> wait? -> proc -> end
491	function phaseStep(w) {
492	  const C = w.C;
493	  const now = w.now;
494	  if (C.ph === 'new') {
495	    C.ph = 'alloc';
496	    emit(w, 'inventory', 'allocate', { orderId: C.oid }, `${C.oid}|alloc`, { t: 'al' });
497	    return;
498	  }
499	  if (C.ph === 'alloc') {
500	    const e = C.ek[`${C.oid}|alloc`];
501	    if (!e || e.r !== 'ok' || !e.plan) return;
502	    buildFulfilments(w, planOf(e.plan));
503	    C.ph = 'create';
504	    run1(w, `${C.oid}|create`, 'orders', 'create', C.cr, { t: 'cr' }, true);
505	    return;
506	  }
507	  if (C.ph === 'create') {
508	    if (run1(w, `${C.oid}|create`, 'orders', 'create', C.cr, { t: 'cr' }, true) === 'ok') C.ph = 'fraud';
509	    return;
510	  }
511	  if (C.ph === 'fraud') {
512	    const frK = `${C.oid}|fr`;
513	    if (!C.ek[frK]) emit(w, 'fraud', 'check', { orderId: C.oid }, frK, { t: 'fr' });
514	    if (!C.fr) {
515	      if (takeCancel(C)) cancelOrder(w, 'customer');
516	      return;
517	    }
518	    if (C.fr === 'reject') return cancelOrder(w, 'fraud');
519	    if (C.fr === 'review') return openReview(w);
520	    return clearOrder(w, C.p);
521	  }
522	  if (C.ph === 'review') {
523	    const rv = C.rv;
524	    if (takeCancel(C)) return cancelOrder(w, 'customer');
525	    if (rv.ans && rv.ans.t <= rv.dl) {
526	      if (rv.ans.d === 'reject') return cancelOrder(w, 'fraud');
527	      return clearOrder(w, rv.ans.t);
528	    }
529	    if (now > rv.dl) return cancelOrder(w, 'fraud-review-timeout');
530	    if (rv.reask) {
531	      rv.reask = false;
532	      rv.n += 1;
533	      openTask(w);
534	    }
535	    return;
536	  }
537	  if (C.ph === 'wait') {
538	    const D = C.D;
539	    const due = C.ac.filter(a => !a.u && a.t <= D).sort((x, y) => x.t - y.t);
540	    const first = due.find(a => a.a === 'amend' || a.a === 'cancel');
541	    for (const a of due) a.u = true;
542	    if (first) return first.a === 'cancel' ? cancelOrder(w, 'customer') : amend(w);
543	    if (now > D) timeOut(w);
544	    return;
545	  }
546	  if (C.ph === 'proc') {
547	    const cancels = C.ac.filter(a => !a.u && a.a === 'cancel').sort((x, y) => x.t - y.t);
548	    for (const a of C.ac) if (a.a === 'amend') a.u = true;
549	    for (const a of cancels) {
550	      a.u = true;
551	      if (collectedBy(C, a.t)) {
552	        notify(w, 'cancel-refused', C.oid, `Your order ${C.oid} can no longer be cancelled: it has been collected.`, `|${a.t}`);
553	      } else {
554	        return cancelOrder(w, 'customer');
555	      }
556	    }
557	  }
558	}
559	
560	// ---------- R4.2 forward steps (one saga per fulfilment) ----------
561	function stepReserve(w, F, go) {
562	  const C = w.C;
563	  const ik = sku => fk(C, F, `r|${sku}`);
564	  const rs = F.items.map(i => ({ sku: i.sku, qty: i.qty, s: settle(w, ik(i.sku)) }));
565	  if (rs.some(x => x.s === 'pend')) return;
566	  if (rs.every(x => x.s === 'ok')) {
567	    F.resOk = true;
568	    return;
569	  }
570	  if (rs.some(x => x.s === 'no' && C.ek[ik(x.sku)].p && !invalidArgs(C.ek[ik(x.sku)]))) return failFul(w, F, 'reserve');
571	  if (!go) return;
572	  if (F.na >= 4) return failFul(w, F, 'reserve');
573	  const need = rs.filter(x => x.s !== 'ok');
574	  F.na += 1;
575	  const ik2 = {};
576	  for (const x of need) {
577	    ik2[x.sku] = ik(x.sku);
578	    track(w, ik(x.sku), 'inventory');
579	  }
580	  // A batch carries no top-level key: each item is keyed (R4.2, api/inventory.schema.json).
581	  w.out.effects.push({
582	    system: 'inventory', op: 'reserve',
583	    args: { orderId: C.oid, fulfilmentId: F.id, location: F.loc, items: need.map(x => ({ key: ik(x.sku), sku: x.sku, qty: x.qty })) },
584	  });
585	}
586	
587	function forward(w, F) {
588	  const C = w.C;
589	  const go = !C.stopped && !F.fail;
590	  if (!F.resOk) return stepReserve(w, F, go);
591	  if (!go) return;
592	  const c = run1(w, fk(C, F, 'ch'), 'billing', 'charge', {
593	    orderId: C.oid, fulfilmentId: F.id, customerId: C.cust, amountMinor: F.amt, currency: C.cur,
594	  }, { t: 'ch' }, true);
595	  if (c === 'fail') return failFul(w, F, 'charge');
596	  if (c !== 'ok') return;
597	  const s = run1(w, fk(C, F, 'sh'), 'carrier', 'create', {
598	    orderId: C.oid, fulfilmentId: F.id, location: F.loc, ref: F.id,
599	  }, { t: 'sh' }, true);
600	  if (s === 'fail') failFul(w, F, 'ship');
601	}
602	
603	// R5.1 compensation in reverse order: shipment, then refund, then releases. Each step
604	// waits for the one before it to settle; a step that never committed is not undone.
605	function compensate(w, F) {
606	  const C = w.C;
607	  const xs = fk(C, F, 'xs'), sh = fk(C, F, 'sh'), ch = fk(C, F, 'ch'), rf = fk(C, F, 'rf');
608	  if (settle(w, sh) === 'pend') return;
609	  if (settle(w, sh) === 'ok' && !F.cfl && !C.ek[xs]) {
610	    F.xs = true;
611	    emit(w, 'carrier', 'cancel', { orderId: C.oid, fulfilmentId: F.id }, xs, { t: 'xs' });
612	  }
613	  if (C.ek[xs] && settle(w, xs) === 'pend') return;
614	  const chS = settle(w, ch);
615	  if (chS === 'pend') return;
616	  if (chS === 'ok' && !C.ek[rf]) {
617	    emit(w, 'billing', 'refund', { orderId: C.oid, fulfilmentId: F.id, amountMinor: F.amt }, rf, { t: 'rf' });
618	  }
619	  if (C.ek[rf] && settle(w, rf) === 'pend') return;
620	  for (const sku of [...new Set(F.items.map(i => i.sku))]) {
621	    const s = settle(w, fk(C, F, `r|${sku}`));
622	    if (s === 'pend') return;
623	    const rl = fk(C, F, `rl|${sku}`);
624	    if (s === 'ok' && !C.ek[rl]) emit(w, 'inventory', 'release', { orderId: C.oid, fulfilmentId: F.id, sku }, rl, { t: 'rl' });
625	  }
626	}
627	
628	function advance(w) {
629	  for (let i = 0; i < 6; i++) {
630	    const before = w.C.ph;
631	    phaseStep(w);
632	    if (w.C.ph === before) break;
633	  }
634	  const C = w.C;
635	  if (C.ph === 'proc') for (const F of C.fl) if (F.av) forward(w, F);
636	  for (const F of C.fl) if (F.av && (F.fail || C.stopped) && F.st !== 'completed') compensate(w, F);
637	  if (C.ph === 'proc' && C.fl.length && C.fl.every(F => FINAL.has(F.st))) {
638	    setOrd(w, C.fl.some(F => F.st === 'completed') ? 'completed' : C.fl.some(F => F.st === 'failed') ? 'failed' : 'cancelled');
639	    C.ph = 'end';
640	  }
641	}
642	
643	// ---------- obligations (wake-ups at deadlines; each fires one minute after its deadline) ----------
644	function obligations(w) {
645	  const C = w.C;
646	  const want = {};
647	  if (C.ph === 'review' && C.rv) want[`${C.oid}-review-deadline`] = { due: C.rv.dl + MIN, on: 'fraudReviewDeadline' };
648	  if (C.ph === 'wait') want[`${C.oid}-customer-deadline`] = { due: C.D + MIN, on: 'customerDeadline' };
649	  for (const [id, o] of Object.entries(want)) {
650	    if (C.ob[id] === o.due) continue;
651	    C.ob[id] = o.due;
652	    w.out.obligations.upsert.push({ id, kind: 'deadline', anchor: isoAms(C.p), dueAt: isoAms(o.due), onDue: o.on });
653	  }
654	  for (const id of Object.keys(C.ob)) {
655	    if (want[id]) continue;
656	    delete C.ob[id];
657	    w.out.obligations.cancel.push(id);
658	  }
659	}
660	
661	function finish(w) {
662	  const C = w.C;
663	  obligations(w);
664	  const pending = Object.entries(C.ek).some(([k, e]) => e.r == null || (e.r === 'unk' && settle(w, k) === 'pend'));
665	  w.out.decisions = { subject: C.oid };
666	  w.out.carry = C;
667	  if (C.ph === 'end' && !pending) w.out.close = true;
668	  return w.out;
669	}
670	
671	// ---------- the arm ----------
672	function tick(input, ctx) {
673	  const w = {
674	    C: input.carry && typeof input.carry === 'object' ? input.carry : null,
675	    out: emptyOut(), ctx, now: T(input.now), instance: input.instance, codes: null,
676	  };
677	  const events = input.events || [];
678	  if (!w.C) {
679	    const early = route(w, events);
680	    if (early) return early;
681	    initRules(w);
682	  }
683	  for (const e of events) applyEvent(w, e);
684	  advance(w);
685	  return finish(w);
686	}
687	
688	export function createSolver() {
689	  return { id: 'solver', tick };
690	}
691

