// ---------- files: ctx.files holds the rulebook, master data and api files (JSON or CSV) ----------
function listFiles(ctx) {
  const f = ctx.files;
  try {
    if (f instanceof Map) return [...f.keys()];
    if (Array.isArray(f)) return f.map(x => (typeof x === 'string' ? x : x.path));
